<?php require_once __DIR__.'/../config/bootstrap.php';$admin=requireAdmin();$m=$_SERVER['REQUEST_METHOD'];
try{
if($m==='GET'){ $q=trim((string)($_GET['q']??'')); if($q!==''){$l="%$q%";$s=db()->prepare('SELECT id,username,email,full_name,role,status,created_at,updated_at FROM accounts WHERE username LIKE ? OR email LIKE ? OR full_name LIKE ? ORDER BY id DESC');$s->execute([$l,$l,$l]);}else{$s=db()->query('SELECT id,username,email,full_name,role,status,created_at,updated_at FROM accounts ORDER BY id DESC');}jsonResponse(['success'=>true,'accounts'=>$s->fetchAll()]);}
if($m==='PUT'){ $d=inputJson();$id=(int)($d['id']??0);$n=trim((string)($d['full_name']??''));$r=(string)($d['role']??'user');$st=(string)($d['status']??'active');$pw=(string)($d['password']??''); if($id<=0||!in_array($r,['admin','user'],true)||!in_array($st,['active','locked'],true))jsonResponse(['success'=>false,'message'=>'Dữ liệu tài khoản không hợp lệ.'],422); if($id===$admin['id']&&($r!=='admin'||$st!=='active')){$c=(int)db()->query("SELECT COUNT(*) FROM accounts WHERE role='admin' AND status='active'")->fetchColumn();if($c<=1)jsonResponse(['success'=>false,'message'=>'Phải giữ lại ít nhất một admin đang hoạt động.'],422);} if($pw!==''){if(strlen($pw)<6)jsonResponse(['success'=>false,'message'=>'Mật khẩu mới phải có ít nhất 6 ký tự.'],422);$s=db()->prepare('UPDATE accounts SET full_name=?,role=?,status=?,password_hash=? WHERE id=?');$s->execute([$n,$r,$st,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{$s=db()->prepare('UPDATE accounts SET full_name=?,role=?,status=? WHERE id=?');$s->execute([$n,$r,$st,$id]);}jsonResponse(['success'=>true,'message'=>'Đã cập nhật tài khoản.']);}
if($m==='DELETE'){ $d=inputJson();$id=(int)($d['id']??0);if($id<=0||$id===$admin['id'])jsonResponse(['success'=>false,'message'=>'Không thể xóa tài khoản admin hiện tại.'],422);$s=db()->prepare('DELETE FROM accounts WHERE id=?');$s->execute([$id]);jsonResponse(['success'=>true,'message'=>'Đã xóa tài khoản.']);}
jsonResponse(['success'=>false,'message'=>'Method không được hỗ trợ.'],405); }catch(Throwable $e){error_log($e->getMessage());jsonResponse(['success'=>false,'message'=>'Lỗi máy chủ hoặc cơ sở dữ liệu.'],500);}
